func syncMemoryProjectionVectors(ctx context.Context, brainDir string, now time.Time) (bool, error) {
	if strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")) == "" {
		return false, nil
	}
	e := historySemanticEmbedder(defaultEmbedder())
	if e == nil {
		return false, nil
	}
	_, pending, err := syncMemoryProjectionVectorsWithEmbedder(ctx, brainDir, now, e, memoryVectorBatchRecords)
	return pending, err
}

// syncMemoryProjectionVectorsWithEmbedder is the only writer for projection
// vector stores. Every destructive reset and every incremental upsert is bound
// to the exact manifest and tombstone identities captured before embedding,
// plus the exact current progress leaf owned by this pass. The pass advances
// that ownership after each of its progress writes. This makes a concurrent
// privacy purge, projection replacement, or progress takeover a closed failure:
// stale vectors cannot be published after any authority changes.
func syncMemoryProjectionVectorsWithEmbedder(ctx context.Context, brainDir string, now time.Time, e Embedder, batchRecords int) (memoryVectorSyncPass, bool, error) {
	var pass memoryVectorSyncPass
	if e == nil {
		return pass, false, nil
	}
	if batchRecords <= 0 {
		batchRecords = memoryVectorBatchRecords
	}
	epoch, manifest, err := captureMemoryVectorEpoch(brainDir)
	if err != nil || manifest.Sources == nil || manifest.Sources.History == nil {
		return pass, false, err
	}
	privacyIdentity := manifest.Sources.History.PrivacyIdentity
	if privacyIdentity != epoch.tombstoneIdentity && !(privacyIdentity == "" && epoch.tombstoneIdentity == "absent") {
		return pass, true, fmt.Errorf("%s: history generation does not match the current privacy epoch", memoryErrSourceStale)
	}
	targetDigest := manifest.Sources.History.IndexDigest
	if !validSHA256Identity(targetDigest) {
		// A history source published before generation-addressed projections
		// carries no index_digest, and the codebase models that as a supported
		// state. SourceDigest is the vector store's binding to the exact
		// projection it was built from, and decodeMemoryVectorProgress requires
		// a valid sha256, so writing a digest-less progress leaf would create a
		// file this very process can never read back: the next ownership
		// validation fails memory_state_corrupt and every later pass refuses to
		// run, wedging vector sync with its own output. There is nothing to
		// bind to yet, so do no work and stay un-pending; the next projection
		// publish stamps a digest and the pass resumes normally.
		return pass, false, nil
	}
	prior, present, ownership, progressErr := loadMemoryVectorProgressWithOwnership(brainDir)
	if progressErr != nil {
		// Content-free progress is still durable state. Unknown-newer, unsafe,
		// and corrupt leaves remain byte-for-byte read-only until an explicit
		// repair/migration action replaces them.
		return pass, true, progressErr
	}
	rawHistoryStore, ok := historyVectorStoreFor(brainDir, e)
	if !ok {
		return pass, false, nil
	}
	historyStore := &memoryGuardedVectorStore{brainDir: brainDir, epoch: epoch, ownership: ownership, store: rawHistoryStore}
	var conversationStore historyVectorStore
	if rawConversationStore, available := newConversationVectorStore(brainDir, conversationVectorModelID(e.ID()), e.Dim()); available {
		conversationStore = &memoryGuardedVectorStore{brainDir: brainDir, epoch: epoch, ownership: ownership, store: rawConversationStore}
	}
	index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
	if err != nil {
		return pass, false, err
	}
	needsReset := memoryVectorProgressNeedsReset(prior, present, e.ID(), targetDigest)
	progress := memoryVectorProgress{ModelID: e.ID(), SourceDigest: targetDigest, UpdatedAt: now, Pending: true}
	if !needsReset {
		progress = prior
		progress.HistoryAdded = 0
		progress.ConversationAdded = 0
		progress.ErrorCode = ""
		progress.UpdatedAt = now
	}
	if needsReset {
		// Persist the reset intent before deleting anything. A crash at any point
		// leaves reset_complete=false, so the next pass finishes clearing stale
		// vectors before it can treat stable IDs as reusable.
		if err := saveMemoryVectorProgressAtEpochOwned(brainDir, epoch, ownership, progress); err != nil {
			return pass, true, err
		}
		pass.HistoryDropped, err = clearMemoryVectorStore(ctx, historyStore)
		if err != nil {
			return pass, true, err
		}
		if conversationStore != nil {
			pass.ConversationDrop, err = clearMemoryVectorStore(ctx, conversationStore)
			if err != nil {
				return pass, true, err
			}
		}
		progress.ResetComplete = true
		if err := saveMemoryVectorProgressAtEpochOwned(brainDir, epoch, ownership, progress); err != nil {
			return pass, true, err
		}
	}
	historyAdded, historyDropped, historyTotal, historyPending, syncErr := syncVectorsForKindsContextBatch(ctx, historyStore, index, e, historyGeneralRankingHiddenKind, func(r historyRecord) string { return r.Summary }, batchRecords)
	pass.HistoryAdded = historyAdded
	pass.HistoryDropped += historyDropped
	pass.HistoryTotal = historyTotal
	progress.HistoryAdded = historyAdded
	remainingBudget := batchRecords - historyAdded
	if remainingBudget < 0 {
		remainingBudget = 0
	}
	conversationPending := false
	if syncErr == nil && conversationStore != nil {
		if remainingBudget == 0 {
			conversationPending = vectorStoreHasMissing(conversationStore, index, conversationSemanticHiddenKind)
		} else {
			conversationAdded, conversationDropped, conversationTotal, pending, conversationErr := syncVectorsForKindsContextBatch(ctx, conversationStore, index, e, conversationSemanticHiddenKind, conversationEmbeddingText, remainingBudget)
			pass.ConversationAdded = conversationAdded
			pass.ConversationDrop += conversationDropped
			pass.ConversationTotal = conversationTotal
			progress.ConversationAdded = conversationAdded
			conversationPending = pending
			if conversationErr != nil {
				syncErr = conversationErr
			}
		}
	}
	progress.Pending = historyPending || conversationPending || syncErr != nil
	if syncErr != nil {
		progress.ErrorCode = "memory_vector_sync_failed"
	} else if !progress.Pending {
		progress.CompleteSourceDigest = targetDigest
	}
	if progressErr := saveMemoryVectorProgressAtEpochOwned(brainDir, epoch, ownership, progress); progressErr != nil {
		syncErr = errors.Join(syncErr, fmt.Errorf("memory_vector_progress_write_failed: %w", progressErr))
	}
	return pass, progress.Pending, syncErr
}

func syncMemoryProjectionVectorsFully(ctx context.Context, brainDir string, now time.Time, e Embedder, progress func(memoryVectorSyncPass)) (memoryVectorSyncPass, error) {
	var total memoryVectorSyncPass
	for {
		if err := ctx.Err(); err != nil {
			return total, err
		}
		pass, pending, err := syncMemoryProjectionVectorsWithEmbedder(ctx, brainDir, now, e, memoryVectorBatchRecords)
		total.HistoryAdded += pass.HistoryAdded
		total.HistoryDropped += pass.HistoryDropped
		total.HistoryTotal = pass.HistoryTotal
		total.ConversationAdded += pass.ConversationAdded
		total.ConversationDrop += pass.ConversationDrop
		total.ConversationTotal = pass.ConversationTotal
		if progress != nil {
			progress(total)
		}
		if err != nil {
			return total, err
		}
		if !pending {
			return total, nil
		}
		if pass.HistoryAdded+pass.ConversationAdded == 0 {
			return total, errors.New("memory_vector_sync_failed: vector sync made no progress")
		}
	}
}

func runMemoryVectorLane(ctx context.Context, brainDir string, now time.Time, owner string) memoryWorkerStats {
	var stats memoryWorkerStats
	if strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")) == "" {
		return stats
	}
	// This lane always runs after deterministic and abstract work. The overall
	// deadline, in addition to each call timeout, caps coordinator occupancy and
	// guarantees a prompt opportunity for shutdown or newly exported work.
	laneCtx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	pending, err := syncMemoryProjectionVectors(laneCtx, brainDir, now)
	laneYielded := errors.Is(laneCtx.Err(), context.DeadlineExceeded)
	stats.VectorPending = pending || laneYielded
	// Only a clean batch or a deliberate lane yield earns the fast relaunch; a
	// failed sync must wait for the next trigger instead of self-spinning.
	stats.VectorContinue = stats.VectorPending && (err == nil || laneYielded)
	if err != nil {
		stats.addHealthIssue("memory_vector_sync_failed")
		if logErr := appendMemoryWorkerLog(brainDir, now, "vector_sync_failed", owner); logErr != nil {
			stats.addHealthIssue("memory_worker_log_write_failed")
		}
	} else if logErr := appendMemoryWorkerLog(brainDir, now, "vector_sync_complete", owner); logErr != nil {
		stats.addHealthIssue("memory_worker_log_write_failed")
	}
	return stats
}

func runMemoryAbstractLane(ctx context.Context, repoDir, brainDir string, now time.Time, owner string) (memoryWorkerStats, error) {
	return runMemoryAbstractLaneWithClock(ctx, repoDir, brainDir, fixedMemoryClock(now), owner)
}

func runMemoryAbstractLaneWithClock(ctx context.Context, repoDir, brainDir string, clock memoryClock, owner string) (memoryWorkerStats, error) {
	var stats memoryWorkerStats
	if _, _, err := loadSessionTombstonesChecked(brainDir); err != nil {
		return stats, err
	}
	var claimed *memoryJob
	claimAt := memoryClockNow(clock)
	err := withBrainWriteLock(brainDir, func() error {
		created, err := reconcileAbstractJobsLocked(brainDir, "worker", claimAt)
		if err != nil {
			return err
		}
		stats.JobsCreated = created
		inventory := loadMemoryJobInventory(brainDir)
		if err := memoryJobEnumerationError(inventory.Issues); err != nil {
			return "", nil, fmt.Errorf("%s: SQLite store or WAL path changed while snapshotting: %w", memoryErrStateUnsafe, aliasErr)
		}
		current, present, infoErr := privacyArtifactInfo(brainDir, source.rel, "SQLite snapshot source")
		if infoErr != nil || !present || !os.SameFile(source.expected, current) || current.Size() != source.expected.Size() || !current.ModTime().Equal(source.expected.ModTime()) {
			cleanup()
			return "", nil, fmt.Errorf("%s: SQLite store or WAL identity changed while snapshotting", memoryErrStateUnsafe)
		}
	}
	if !walPresent {
		if _, present, infoErr := privacyArtifactInfo(brainDir, walRel, "SQLite WAL"); infoErr != nil || present {
			cleanup()
			return "", nil, fmt.Errorf("%s: SQLite WAL appeared while snapshotting", memoryErrStateUnsafe)
		}
	}

	// Replay committed WAL frames only inside the trusted temporary directory.
	// The later immutable readers can now inspect one self-contained main file.
	db, err := sql.Open(sqliteDriverName, snapshotPath)
	if err != nil {
		cleanup()
		return "", nil, fmt.Errorf("%s: open private SQLite snapshot: %w", memoryErrStateCorrupt, err)
	}
	db.SetMaxOpenConns(1)
	var busy, logFrames, checkpointedFrames int
	checkpointErr := db.QueryRow(`PRAGMA wal_checkpoint(TRUNCATE)`).Scan(&busy, &logFrames, &checkpointedFrames)
	closeErr := db.Close()
	if checkpointErr != nil || closeErr != nil || busy != 0 || (logFrames > 0 && checkpointedFrames != logFrames) {
		cleanup()
		return "", nil, fmt.Errorf("%s: replay private SQLite WAL before verification", memoryErrStateCorrupt)
	}
	return snapshotPath, cleanup, nil
}

func inspectPrivacyVectorIDsSnapshot(snapshot, rel string, wanted map[string]struct{}, findingSessionID string) ([]privacyVerifyFinding, error) {
	db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(snapshot))
	if err != nil {
		return nil, fmt.Errorf("%s: open vector store %s: %w", memoryErrStateCorrupt, rel, err)
	}
	defer db.Close()
	var integrity string
	if err := db.QueryRow(`PRAGMA quick_check`).Scan(&integrity); err != nil || integrity != "ok" {
		return nil, fmt.Errorf("%s: vector store %s failed integrity verification", memoryErrStateCorrupt, rel)
	}
	rows, err := db.Query(fmt.Sprintf(`SELECT record_id FROM history_ids LIMIT %d`, privacyVectorVerifyMaxRows+1))
	if err != nil {
		return nil, fmt.Errorf("%s: inspect vector IDs in %s: %w", memoryErrStateCorrupt, rel, err)
	}
	defer rows.Close()
	var findings []privacyVerifyFinding
	count := 0
	for rows.Next() {
		count++
		if count > privacyVectorVerifyMaxRows {
			return nil, fmt.Errorf("%s: vector store %s exceeds verification ceiling", memoryErrStateUnsafe, rel)
		}
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("%s: inspect vector ID in %s: %w", memoryErrStateCorrupt, rel, err)
		}
		if _, current := wanted[id]; !current {
			findings = append(findings, privacyVerifyFinding{
				SessionID: findingSessionID,
				Artifact:  "vector_store",
				Detail:    rel + " contains record " + id + " outside the current tombstone-filtered history generation; rebuild vectors",
			})
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%s: inspect vector IDs in %s: %w", memoryErrStateCorrupt, rel, err)
	}
	return findings, nil
}

const privacyCorpusVerifyMaxRows = 2_000_000

// inspectPrivacyPatternCorpus performs row-level attribution over the corpus,
// including path aliases whose session_id is blank or different. Mtime and
// integrity alone cannot prove a valid SQLite file was rebuilt from clean
// inputs after the tombstone landed.
func inspectPrivacyPatternCorpus(snapshotPath string, stones sessionTombstones, pathsBySession map[string]map[string]bool, expectedPolicyIdentity, findingSessionID string) ([]privacyVerifyFinding, error) {
	ownerByPath := map[string]string{}
	for id, paths := range pathsBySession {
		for rel := range paths {
			ownerByPath[normalizePrivacyTranscriptPath(rel)] = id
		}
	}
	db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(snapshotPath))
	if err != nil {
		return nil, fmt.Errorf("%s: open %s: %w", memoryErrStateCorrupt, patternCorpusPath, err)
	}
	defer db.Close()
	type corpusTable struct {
		name       string
		pathColumn string
		artifact   string
	}
	var findings []privacyVerifyFinding
	if got := corpusMeta(db, "privacy_policy_identity"); got != expectedPolicyIdentity {
		findings = append(findings, privacyVerifyFinding{
			SessionID: findingSessionID,
			Artifact:  "pattern_corpus_policy",
			Detail:    "corpus was not built under the current tombstone policy; rebuild patterns before serving it",
		})
	}
	seen := map[string]bool{}
	for _, table := range []corpusTable{
		{name: "indexed_sessions", pathColumn: "transcript_path", artifact: "pattern_corpus_session"},
		{name: "episodes", pathColumn: "source_path", artifact: "pattern_corpus_episode"},
	} {
		query := fmt.Sprintf("SELECT id, session_id, %s FROM %s LIMIT %d", table.pathColumn, table.name, privacyCorpusVerifyMaxRows+1)
		rows, err := db.Query(query)
		if err != nil {
			return nil, fmt.Errorf("%s: inspect %s %s: %w", memoryErrStateCorrupt, patternCorpusPath, table.name, err)
		}
		count := 0
		for rows.Next() {
			count++
			if count > privacyCorpusVerifyMaxRows {
				rows.Close()
				return nil, fmt.Errorf("%s: %s %s exceeds %d rows", memoryErrStateCorrupt, patternCorpusPath, table.name, privacyCorpusVerifyMaxRows)
			}
			var rowID, sessionID, sourcePath string
			if err := rows.Scan(&rowID, &sessionID, &sourcePath); err != nil {
				rows.Close()
				return nil, fmt.Errorf("%s: scan %s %s: %w", memoryErrStateCorrupt, patternCorpusPath, table.name, err)
			}
			owner := ""
			if _, excluded := stones.Excluded[strings.TrimSpace(sessionID)]; excluded {
				owner = strings.TrimSpace(sessionID)
			} else {
				owner = ownerByPath[normalizePrivacyTranscriptPath(sourcePath)]
			}
			key := table.artifact + "\x00" + owner
			if owner != "" && !seen[key] {
				seen[key] = true
				findings = append(findings, privacyVerifyFinding{
					SessionID: owner,
					Artifact:  table.artifact,
					Detail:    fmt.Sprintf("%s row %s retains excluded session/path %s", table.name, rowID, normalizePrivacyTranscriptPath(sourcePath)),
				})
			}
		}
		if err := rows.Err(); err != nil {
			rows.Close()
			return nil, fmt.Errorf("%s: iterate %s %s: %w", memoryErrStateCorrupt, patternCorpusPath, table.name, err)
		}
		rows.Close()
	}
	return findings, nil
}

func loadPrivacyTransactionChecked(brainDir, sessionID string) (privacyTransaction, bool, error) {
	rel := privacyTransactionRel(sessionID)
	data, present, err := readPrivacyArtifact(brainDir, rel, "privacy transaction", maxManifestBytes)
	if err != nil || !present {
		return privacyTransaction{}, present, err
	}
	tx, err := decodePrivacyTransaction(data, sessionID)
	if err != nil {
		return privacyTransaction{}, true, err
	}
	return tx, true, nil
}

func decodePrivacyTransaction(data []byte, sessionID string) (privacyTransaction, error) {
	var tx privacyTransaction
	version, err := decodeStrictVersionedJSON(data, &tx, privacyTransactionVersion, "privacy transaction")
	if err != nil {
		return privacyTransaction{}, err
	}
	validState := tx.State == privacyStateRequested || tx.State == privacyStateGuarded || tx.State == privacyStateRebuilding ||
		tx.State == privacyStateVerified || tx.State == privacyStateComplete || tx.State == privacyStateError
	if (version != privacyTransactionLegacyVersion && version != privacyTransactionVersion) || tx.SchemaVersion != version || tx.SessionID != sessionID ||
		(tx.Operation != "exclude" && tx.Operation != "purge") || !validState || tx.StartedAt.IsZero() || tx.UpdatedAt.IsZero() ||
		tx.UpdatedAt.Before(tx.StartedAt) {
		return privacyTransaction{}, fmt.Errorf("%s: invalid privacy transaction %s", memoryErrStateCorrupt, privacyTransactionRel(sessionID))
	}
	for _, artifact := range tx.Artifacts {
		if strings.TrimSpace(artifact.Path) == "" || artifact.Bytes < 0 {
			return privacyTransaction{}, fmt.Errorf("%s: invalid privacy transaction artifact %s", memoryErrStateCorrupt, privacyTransactionRel(sessionID))
		}
	}
	if len(tx.SessionRefs) > privacyTransactionSessionRefMax {
		return privacyTransaction{}, fmt.Errorf("%s: privacy transaction has too many session refs %s", memoryErrStateCorrupt, privacyTransactionRel(sessionID))
	}
	seenRefs := map[string]bool{}
	for _, ref := range tx.SessionRefs {
		if !strings.HasPrefix(ref, conversationSessionIDPrefix) || strings.TrimSpace(strings.TrimPrefix(ref, conversationSessionIDPrefix)) == "" || seenRefs[ref] {
			return privacyTransaction{}, fmt.Errorf("%s: invalid privacy transaction session ref %s", memoryErrStateCorrupt, privacyTransactionRel(sessionID))
		}
		seenRefs[ref] = true
	}
	return tx, nil
}

// privacyDerivedReadGate prevents the tombstone-first cleanup window from
// exposing corpus-derived content. A valid tombstone does not permanently
// disable patterns: once the authoritative full verification is clean, reads
// resume normally.
func privacyDerivedReadGate(brainDir string) (bool, error) {
	// The corpus is optional, but when present its main database and WAL must be
	// ordinary Brain-owned files even when there are no tombstones. Without this
	// unconditional check, best-effort pattern loaders could hide an unsafe alias
	// as an empty result on status/get/skill surfaces.
	if err := validatePatternCorpusReadSafety(brainDir); err != nil {
		return false, err
	}
	stones, _, err := loadSessionTombstonesChecked(brainDir)
	if err != nil {
		return false, err
	}
	if len(stones.Excluded) == 0 {
		return true, nil
	}
	report, err := verifySessionPrivacy(brainDir)
	if err != nil {
		return false, err
	}
	return report.Clean, nil
}

func requirePrivacyDerivedRead(brainDir string) error {
	allowed, err := privacyDerivedReadGate(brainDir)
	if err != nil {
		return err
	}
	if !allowed {
		return fmt.Errorf("%s: derived pattern state is unavailable until excluded-session cleanup verifies clean; run `entire brain privacy purge <session-id>`", memoryErrPrivacyDirty)
	}
	return nil
}

